member_geometry <- function(nodes,members,node_dofs) {
  lapply(members,function(m) {
    start <- nodes[[m$start]]
    finish <- nodes[[m$finish]]
    dx <- finish$x-start$x
    dy <- finish$y-start$y
    span <- sqrt(dx*dx+dy*dy)
    list(length=span,cosine=dx/span,sine=dy/span,dofs=c(node_dofs[[m$start]],node_dofs[[m$finish]]))
  })
}
member_properties <- function(model,choices,geometry) {
  lapply(seq_along(model$members),function(i) {
    member <- model$members[[i]]
    section <- model$sections[[choices[i]]]
    material <- model$materials[[member$material]]
    list(
        area=section$area,
        inertia=section$inertia,
        young=material$young,
        yield_stress=material$yield_stress,
        density=material$density,
        expansion=material$expansion,
        stiffness=material$young*section$area/geometry[[i]]$length
    )
  })
}
member_weight <- function(p,g) p$density*9.81*p$area*g$length/1000000000
member_stiffness <- function(p,g) {
  k <- p$stiffness
  c <- g$cosine
  s <- g$sine
  xx <- k*(c*c)
  xy <- k*(c*s)
  yy <- k*(s*s)
  matrix(c(xx,xy,-xx,-xy,xy,yy,-xy,-yy,-xx,-xy,xx,xy,-xy,-yy,xy,yy),4L,4L,byrow=TRUE)
}
assemble <- function(geometry,properties,degrees,removed=0L) {
  matrix <- matrix(0,degrees,degrees)
  for (number in seq_along(geometry)) {
    if (number == removed) next
    shape <- geometry[[number]]
    local <- member_stiffness(properties[[number]],shape)
    for (row in seq_len(4L)) for (column in seq_len(4L)) matrix[shape$dofs[row],shape$dofs[column]] <- matrix[
        shape$dofs[row],
        shape$dofs[column]
    ]+local[row,column]
  }
  matrix
}
load_vectors <- function(case,geometry,properties,node_dofs,degrees,removed=0L) {
  external <- thermal <- numeric(degrees)
  temperature <- numeric(length(geometry))
  settlement <- FALSE
  for (line in case$lines) {
    if (line$kind == "FORCE") {
      directions <- node_dofs[[line$node]]
      external[directions[1L]] <- external[directions[1L]]+line$horizontal*1000
      external[directions[2L]] <- external[directions[2L]]+line$vertical*1000
    } else if (line$kind == "TEMPERATURE") {
      number <- line$member
      if (number == removed) next
      p <- properties[[number]]
      g <- geometry[[number]]
      force <- p$young*p$area*p$expansion*line$change
      temperature[number] <- force
      direction <- c(-g$cosine,-g$sine,g$cosine,g$sine)
      for (i in seq_len(4L)) thermal[g$dofs[i]] <- thermal[g$dofs[i]]+force*direction[i]
    } else if (line$kind == "SELFWEIGHT") for (number in seq_along(geometry)) {
      if (number == removed) next
      g <- geometry[[number]]
      weight <- member_weight(properties[[number]],g)
      external[g$dofs[2L]] <- external[g$dofs[2L]]-weight/2
      external[g$dofs[4L]] <- external[g$dofs[4L]]-weight/2
    } else settlement <- TRUE
  }
  list(external=external,total=external+thermal,temperature=temperature,settlement=settlement)
}

TRUSS_PI <- 3.141592653589793
buckling <- function(p,g,inertia=p$inertia) TRUSS_PI*TRUSS_PI*p$young*inertia/(g$length*g$length)
utilization <- function(force,p,g,section=NULL) {
  area <- if (is.null(section)) p$area else section$area
  inertia <- if (is.null(section)) p$inertia else section$inertia
  max(abs(force/area)/p$yield_stress,max(0,-force)/buckling(p,g,inertia))
}
slenderness <- function(p,g,section=NULL) {
  area <- if (is.null(section)) p$area else section$area
  inertia <- if (is.null(section)) p$inertia else section$inertia
  g$length/sqrt(inertia/area)
}
slenderness_limit <- function(number,combinations,limits) if (any(vapply(
    combinations,
    function(r) r$forces[number] < 0,
    logical(1)
))) limits[1L] else limits[2L]
select_section <- function(members,sections,properties,geometry,combinations,limits) {
  for (number in seq_along(sections)) {
    section <- sections[[number]]
    acceptable <- TRUE
    for (member in members) {
      if (slenderness(properties[[member]],geometry[[member]],section) > limits[member] || any(vapply(
          combinations,
          function(r) utilization(r$forces[member],properties[[member]],geometry[[member]],section) > 1,
          logical(1)
      ))) {
        acceptable <- FALSE
        break
      }
    }
    if (acceptable) return(number)
  }
  length(sections)
}

csv_rows <- function(name) strsplit(readLines(paste0("input/",name,".csv"),warn=FALSE)[-1L],",",fixed=TRUE)
read_model <- function() {
  nodes <- lapply(
      csv_rows("nodes"),
      function(r) list(id=as.integer(r[1L]),x=as.integer(r[2L]),y=as.integer(r[3L]))
  )
  sections <- lapply(
      csv_rows("sections"),
      function(r) list(name=r[1L],area=as.numeric(r[2L]),inertia=as.numeric(r[3L]))
  )
  materials <- lapply(
      csv_rows("materials"),
      function(r) list(
          name=r[1L],
          young=as.numeric(r[2L]),
          yield_stress=as.numeric(r[3L]),
          density=as.numeric(r[4L]),
          expansion=as.numeric(r[5L])
      )
  )
  ni <- vapply(nodes,function(n) n$id,integer(1))
  si <- vapply(sections,function(s) s$name,character(1))
  mi <- vapply(materials,function(m) m$name,character(1))
  members <- lapply(
      csv_rows("members"),
      function(r) list(
          id=as.integer(r[1L]),
          start=match(as.integer(r[2L]),ni),
          finish=match(as.integer(r[3L]),ni),
          section=match(r[4L],si),
          material=match(r[5L],mi),
          group=r[6L]
      )
  )
  ei <- vapply(members,function(e) e$id,integer(1))
  supports <- lapply(
      csv_rows("supports"),
      function(r) list(
          node=match(as.integer(r[1L]),ni),
          fixed=as.integer(r[2L:3L]),
          prescribed=as.numeric(r[4L:5L])
      )
  )
  cases <- combinations <- loads <- list()
  name <- ""
  for (line in readLines("input/loads.txt",warn=FALSE)) {
    f <- strsplit(line," ",fixed=TRUE)[[1L]]
    kind <- f[1L]
    if (kind == "LOADCASE") {
      name <- f[2L]
      loads <- list()
    } else if (kind == "END") {
      cases[[length(cases)+1L]] <- list(name=name,lines=loads)
    } else if (kind == "COMBINATION") {
      terms <- lapply(seq.int(3L,length(f),2L),function(i) list(name=f[i],factor=as.numeric(f[i+1L])))
      combinations[[length(combinations)+1L]] <- list(name=f[2L],terms=terms)
    } else if (kind == "FORCE") {
      loads[[length(loads)+1L]] <- list(
          kind=kind,
          node=match(as.integer(f[2L]),ni),
          horizontal=as.numeric(f[3L]),
          vertical=as.numeric(f[4L])
      )
    } else if (kind == "TEMPERATURE") {
      loads[[length(loads)+1L]] <- list(kind=kind,member=match(as.integer(f[2L]),ei),change=as.numeric(f[3L]))
    } else {
      loads[[length(loads)+1L]] <- list(kind=kind)
    }
  }
  settings <- list(influence=integer(),drawing=list())
  for (line in readLines("input/params.txt",warn=FALSE)) {
    f <- strsplit(line," ",fixed=TRUE)[[1L]]
    kind <- f[1L]
    v <- f[-1L]
    if (kind == "deck") {
      settings[[kind]] <- match(as.integer(v),ni)
    } else if (kind == "influence") {
      settings[[kind]] <- c(settings[[kind]],match(as.integer(v[1L]),ei))
    } else if (kind == "vehicle") {
      settings[[kind]] <- list(
          step=as.integer(v[1L]),
          axles=lapply(
              seq.int(2L,length(v),2L),
              function(i) list(offset=as.integer(v[i]),load=as.numeric(v[i+1L]))
          )
      )
    } else if (kind == "rating") {
      settings[[kind]] <- list(name=v[1L],dead=as.numeric(v[2L]),vehicle=as.numeric(v[3L]))
    } else if (kind == "slenderness") {
      settings[[kind]] <- as.numeric(v)
    } else if (kind == "deflection") {
      settings[[kind]] <- list(name=v[1L],ratio=as.integer(v[2L]))
    } else if (kind == "vibration") {
      settings[[kind]] <- list(name=v[1L],modes=as.integer(v[2L]),iterations=as.integer(v[3L]))
    } else if (kind == "removal") {
      settings[[kind]] <- v[1L]
    } else if (kind == "drawing") {
      settings[[kind]][[length(settings[[kind]])+1L]] <- list(
          name=v[1L],
          magnification=as.integer(v[2L]),
          horizontal=as.integer(v[3L]),
          vertical=as.integer(v[4L])
      )
    } else {
      settings[[kind]] <- as.integer(v)
    }
  }
  list(
      nodes=nodes,
      members=members,
      sections=sections,
      materials=materials,
      supports=supports,
      cases=cases,
      combinations=combinations,
      settings=settings
  )
}

axial_forces <- function(geometry,properties,displacement,temperature,removed=0L) {
  forces <- numeric(length(geometry))
  for (number in seq_along(geometry)) {
    if (number == removed) next
    g <- geometry[[number]]
    d <- g$dofs
    extension <- (displacement[d[3L]]-displacement[d[1L]])*g$cosine+(displacement[d[4L]]-displacement[d[2L]])*g$sine
    forces[number] <- properties[[number]]$stiffness*extension-temperature[number]
  }
  forces
}
support_reactions <- function(matrix,displacement,force,restrained) {
  result <- numeric(length(force))
  for (r in restrained) {
    value <- 0
    for (d in seq_along(force)) value <- value+matrix[r,d]*displacement[d]
    result[r] <- value-force[r]
  }
  result
}
superpose <- function(combination,results) {
  term <- combination$terms[[1L]]
  keys <- c("displacement","forces","reactions","external")
  result <- lapply(results[[term$name]][keys],function(vector) term$factor*vector)
  for (term in combination$terms[-1L]) for (key in keys) {
    source <- results[[term$name]][[key]]
    for (i in seq_along(source)) result[[key]][i] <- result[[key]][i]+term$factor*source[i]
  }
  c(list(name=combination$name),result)
}
equilibrium_residual <- function(result,geometry) {
  residual <- result$external+result$reactions
  for (i in seq_along(geometry)) {
    g <- geometry[[i]]
    direction <- c(g$cosine,g$sine,-g$cosine,-g$sine)
    for (j in seq_len(4L)) residual[g$dofs[j]] <- residual[g$dofs[j]]+result$forces[i]*direction[j]
  }
  max(abs(residual))
}

factor_cholesky <- function(matrix,free) {
  n <- nrow(matrix)
  lower <- matrix(0,n,n)
  for (i in seq_len(n)) for (j in seq_len(i)) {
    w <- matrix[i,j]
    for (h in seq_len(j-1L)) w <- w-lower[i,h]*lower[j,h]
    if (j < i) lower[i,j] <- w/lower[j,j] else {
      if (w <= 1e-9*matrix[i,i]) return(list(lower=NULL,unstable=free[i]))
      lower[i,i] <- sqrt(w)
    }
  }
  list(lower=lower,unstable=0L)
}
solve_cholesky <- function(lower,right) {
  n <- length(right)
  intermediate <- result <- numeric(n)
  for (i in seq_len(n)) {
    w <- right[i]
    for (h in seq_len(i-1L)) w <- w-lower[i,h]*intermediate[h]
    intermediate[i] <- w/lower[i,i]
  }
  for (i in rev(seq_len(n))) {
    w <- intermediate[i]
    if (i < n) for (h in seq.int(i+1L,n)) w <- w-lower[h,i]*result[h]
    result[i] <- w/lower[i,i]
  }
  result
}
